function validateSourceBlocks(extract, content) {
  const known = new Set((extract.blocs || []).map((block) => block.id)); const missing = [];
  const visit = (value) => { if (!value || typeof value !== "object") return; if (Array.isArray(value)) { value.forEach(visit); return; } if (Array.isArray(value.sourceBlocks)) for (const id of value.sourceBlocks) if (!known.has(id)) missing.push(id); for (const [key, child] of Object.entries(value)) if (key !== "sourceBlocks") visit(child); };
  visit(content); if (missing.length) throw new Error(`Chapitre 34 : sourceBlocks inconnus : ${[...new Set(missing)].join(", ")}`);
}
export function buildChapter34(extract) { const result = { fiche: buildFiche(), flashcards: buildFlashcards(), series: [...buildIsolatedQcm(), ...buildDpQcm(), ...buildIsolatedQroc(), ...buildDpQroc()] }; validateSourceBlocks(extract, result); return result; }
